<?php
require_once __DIR__ . '/../helpers.php'; require_once __DIR__ . '/../config/database.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));if($name==='')throw new RuntimeException('Nama supplier wajib diisi.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Format email tidak valid.');if($id){$s=$pdo->prepare('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?');$s->execute([$name,$phone?:null,$email?:null,$address?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$s->execute([$name,$phone?:null,$email?:null,$address?:null]);}flash('Supplier disimpan.');}elseif($a==='delete'){require_admin();$s=$pdo->prepare('DELETE FROM suppliers WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Supplier dihapus.');}}catch(Throwable $e){flash($e instanceof PDOException?'Supplier masih dipakai produk atau data tidak valid.':$e->getMessage(),'error');}redirect('suppliers.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT s.*,COUNT(ps.product_id) product_count FROM suppliers s LEFT JOIN product_suppliers ps ON ps.supplier_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();
layout_start('Supplier');
echo '<div class="card"><h2>'.($edit?'Edit Supplier':'Tambah Supplier').'</h2><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><label>Nama</label><input name="name" required value="'.e($edit['name']??'').'"><div class="grid"><div><label>Telepon</label><input name="phone" value="'.e($edit['phone']??'').'"></div><div><label>Email</label><input name="email" type="email" value="'.e($edit['email']??'').'"></div></div><label>Alamat</label><input name="address" value="'.e($edit['address']??'').'"><p><button>Simpan</button> <a class="btn secondary" href="suppliers.php">Batal</a></p></form></div><div class="card table-wrap"><table><tr><th>Nama</th><th>Telepon</th><th>Email</th><th>Produk terkait</th><th>Aksi</th></tr>';
foreach($rows as $r){echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['email']).'</td><td>'.(int)$r['product_count'].'</td><td><a class="btn secondary" href="?edit='.(int)$r['id'].'">Edit</a> ';if(current_user()['role']==='admin')echo '<form method="post" onsubmit="return confirm(\'Hapus supplier?\')"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="danger">Hapus</button></form>';echo '</td></tr>';}
echo '</table></div>';layout_end();
